<template><section class="workspace-page self-test-page"><PageHeader title="从资料里，检验自己的理解" eyebrow="本地自测 · 手动核对" description="多题型由你根据原文编写与核对，不生成服务器成绩、错题或宠物奖励。"/><RouterLink to="/learn?tab=practice" class="workspace-text-action">← 返回权威单选练习</RouterLink><p v-if="message" role="status" class="workspace-caption">{{ message }}</p><form v-if="!testing" class="m-card workspace-form" @submit.prevent="begin"><label class="m-field"><span>关联资料</span><select v-model="draft.materialId" class="m-input"><option value="">不关联资料</option><option v-for="m in store.workspace?.materials || []" :key="m.id" :value="m.id">{{ m.title }}</option></select></label><details v-if="material"><summary>阅读资料原文</summary><p v-for="part in material.sections.slice(0,8)" :key="part.id" class="self-test-source">段 {{ part.paragraph }} · {{ part.text }}</p></details><label class="m-field"><span>题型</span><select v-model="draft.kind" class="m-input"><option v-for="item in kinds" :key="item.value" :value="item.value">{{ item.label }}</option></select></label><label class="m-field"><span>根据资料提出问题</span><textarea v-model="draft.prompt" class="m-textarea" required rows="3" maxlength="2000"/></label><label v-if="['single','multi'].includes(draft.kind)" class="m-field"><span>选项（每行一项，2–8 项）</span><textarea v-model="draft.choices" class="m-textarea" rows="4" maxlength="3000" required/></label><label class="m-field"><span>核对依据与解析（建议填写原文段落）</span><textarea v-model="draft.reference" class="m-textarea" rows="4" maxlength="5000" placeholder="这不是模型标准答案，请以原文或教师确认的结论为准。"/></label><button class="m-btn m-btn--primary">保存草稿并开始自测</button></form><article v-else class="m-card workspace-form"><span class="m-badge m-badge--warn">本地 {{ kinds.find(k=>k.value===draft.kind)?.label }} · 不计入成绩</span><h2>{{ draft.prompt }}</h2><fieldset v-if="['single','multi','boolean'].includes(draft.kind)" :disabled="revealed"><legend>你的作答</legend><label v-for="(choice,i) in choices" :key="i" class="workspace-checkbox"><input v-if="draft.kind==='multi'" v-model="selected" type="checkbox" :value="i"/><input v-else v-model="single" type="radio" name="local-answer" :value="i"/><span>{{ choice }}</span></label></fieldset><label v-else class="m-field"><span>你的作答</span><textarea v-model="answer" :disabled="revealed" class="m-textarea" rows="4" maxlength="5000"/></label><button v-if="!revealed" class="m-btn m-btn--primary" @click="revealed=true;save()">保存作答，查看核对依据</button><template v-else><h3>你填写的核对依据</h3><pre class="self-test-source">{{ draft.reference || '尚无核对依据。请回到原文核实，无法确认时保留不确定。' }}</pre><label class="m-field"><span>核对后的自我判断</span><select v-model="verdict" class="m-input" @change="save"><option value="uncertain">仍不确定</option><option value="understood">自评理解</option><option value="review">需要复习</option></select></label><p class="workspace-caption">此判断仅是本机自评，不会改变能力图谱或服务器判分。</p><RouterLink v-if="material" :to="{path:'/agent',query:{material:material.id,kind:'materials'}}" class="m-btn m-btn--ghost">带着原文向星枢提问</RouterLink><button class="m-btn m-btn--ghost" @click="testing=false;save()">编辑题目与依据</button></template></article><p class="workspace-caption">草稿、作答与自评按账号保存在本机。要提交权威评分，请使用题库单选练习。刷新后可恢复最近这份自测。</p><button class="workspace-text-action" @click="exportDraft">导出自测 Markdown</button><p v-if="store.storageError" class="m-error">{{ store.storageError }}</p></section></template>
<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import PageHeader from '@/mobile/components/PageHeader.vue'
import {useLearningWorkspace} from '@/mobile/stores/learning-workspace'
import {downloadText} from '@/mobile/data/workspace'
const store=useLearningWorkspace(),kinds=[{value:'single',label:'单选题'},{value:'multi',label:'多选题'},{value:'boolean',label:'判断题'},{value:'fill',label:'填空题'},{value:'short',label:'简答题'}],draft=ref({materialId:'',kind:'short',prompt:'',choices:'',reference:''}),testing=ref(false),revealed=ref(false),selected=ref<number[]>([]),single=ref(-1),answer=ref(''),verdict=ref('uncertain'),message=ref('')
const material=computed(()=>store.workspace?.materials.find(m=>m.id===draft.value.materialId)),choices=computed(()=>draft.value.kind==='boolean'?['正确','错误']:draft.value.choices.split('\n').map(s=>s.trim()).filter(Boolean).slice(0,8))
let restoring=true
onMounted(async()=>{await store.refresh();try{const x=JSON.parse(store.local.selfTest||'null');if(x&&kinds.some(k=>k.value===x.draft?.kind)&&['prompt','choices','reference','materialId'].every(k=>typeof x.draft[k]==='string')){draft.value=x.draft;testing.value=x.testing===true;revealed.value=x.revealed===true;answer.value=typeof x.answer==='string'?x.answer:'';selected.value=Array.isArray(x.selected)?x.selected.filter((n:unknown)=>Number.isInteger(n)&&Number(n)>=0&&Number(n)<8):[];single.value=Number.isInteger(x.single)?x.single:-1;verdict.value=['uncertain','understood','review'].includes(x.verdict)?x.verdict:'uncertain'}}catch{}restoring=false})
function save(){if(restoring)return;store.local.selfTest=JSON.stringify({draft:draft.value,testing:testing.value,revealed:revealed.value,selected:selected.value,single:single.value,answer:answer.value,verdict:verdict.value});store.persist()}
watch([draft,answer,single,selected],save,{deep:true})
function begin(){if(['single','multi'].includes(draft.value.kind)&&choices.value.length<2){message.value='请选择题型并填写至少两个选项。';return}testing.value=true;revealed.value=false;single.value=-1;selected.value=[];answer.value='';verdict.value='uncertain';message.value='';save()}
function exportDraft(){downloadText('我的本地自测.md',`# 本地自测（非服务器成绩）\n\n${draft.value.prompt}\n\n${choices.value.join('\n')}\n\n作答：${answer.value||selected.value.map(i=>choices.value[i]).join('、')||choices.value[single.value]||'未作答'}\n\n核对依据：${draft.value.reference}\n\n自评：${verdict.value}`)}
</script>
<style scoped>.self-test-page>.m-card{margin-top:20px}.self-test-source{font:inherit;font-size:14px;white-space:pre-wrap;line-height:1.9;overflow-wrap:anywhere;color:var(--m-text-dim)}fieldset{border:1px solid var(--m-border);border-radius:12px}fieldset legend{font-size:13px;color:var(--m-text-faint)}</style>
